"""Rate limits for the API (generated by Shikshya, PX.308). A visitor is told apart by the address of the
connection, or, behind a proxy that sets one, by the header named in the CLIENT_IP_HEADER setting (on Railway:
X-Real-IP, which its edge sets). A client-sent X-Forwarded-For is never read, so a limit cannot be dodged by
forging it. Anonymous reads have their own limit, so a busy public page never uses up what anonymous writes and
sign-in are allowed."""
import ipaddress

from django.conf import settings
from rest_framework import throttling

SAFE_METHODS = ("GET", "HEAD", "OPTIONS")


def client_address(request) -> str:
    """The visitor's address: the trusted proxy header when one is set and holds an address, else the connection."""
    header = str(getattr(settings, "CLIENT_IP_HEADER", "") or "").strip()
    if header:
        value = request.META.get("HTTP_" + header.upper().replace("-", "_"), "").split(",")[0].strip()
        try:
            return str(ipaddress.ip_address(value))
        except ValueError:
            pass
    return request.META.get("REMOTE_ADDR", "")


class ClientAddress:
    def get_ident(self, request):
        return client_address(request)


class AnonReadThrottle(ClientAddress, throttling.AnonRateThrottle):
    """Anonymous GET, HEAD and OPTIONS: the public pages."""
    scope = "anon_read"

    def allow_request(self, request, view):
        return request.method not in SAFE_METHODS or super().allow_request(request, view)


class AnonWriteThrottle(ClientAddress, throttling.AnonRateThrottle):
    """Anonymous writes: forms and sign-up."""
    scope = "anon"

    def allow_request(self, request, view):
        return request.method in SAFE_METHODS or super().allow_request(request, view)


class UserRateThrottle(ClientAddress, throttling.UserRateThrottle):
    """Signed-in users, by user. Anonymous callers are left to anon_read and anon: counted here by address too,
    1000 public reads an hour would block that visitor's writes and sign-in."""

    def allow_request(self, request, view):
        user = getattr(request, "user", None)
        return not (user and user.is_authenticated) or super().allow_request(request, view)


class ScopedRateThrottle(ClientAddress, throttling.ScopedRateThrottle):
    """A view's own scope, such as sign-in's "auth"."""
